as</label><input name="area" placeholder="Contoh: 120 m²"></div><div class="field" style="grid-column:1/-1"><label>Kebutuhan</label><textarea name="message" rows="4" placeholder="Ceritakan kebutuhan Anda..."></textarea></div></div><button class="btn" name="consult" value="1" style="width:100%">Lanjut ke WhatsApp</button></form></div></div><script>const modal=document.getElementById('modal');function openModal(s){modal.classList.add('show');document.body.style.overflow='hidden';if(s){const x=document.getElementById('service');[...x.options].forEach(o=>{if(o.text.toLowerCase().includes(s.toLowerCase().split(' ')[0]))x.value=o.text})}}function closeModal(){modal.classList.remove('show');document.body.style.overflow=''}modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');const f=b.dataset.f;document.querySelectorAll('.project').forEach(p=>p.style.display=f==='all'||p.dataset.cat===f?'block':'none')});function faq(b){b.parentElement.classList.toggle('open')}function calc(){const a=Math.max(10,Number(document.getElementById('area').value)||100),t=document.getElementById('type').value,l=Number(document.getElementById('level').value),r={desain:[80000,140000],bangun:[6500000,9000000],renovasi:[3500000,6000000],interior:[1800000,3200000]}[t],f=n=>n>=1e9?'Rp '+(n/1e9).toFixed(2).replace('.',',')+' M':'Rp '+Math.round(n/1e6)+' Jt';document.getElementById('budget').textContent=f(a*r[0]*l)+' – '+f(a*r[1]*l)}calc();document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});</script></body></html>